// Hindi (हिन्दी): every message the windows show, from the catalogue's list
// (messages.json), in standard Hindi in Devanagari with the words Microsoft
// Office uses in Hindi, a counted message in Hindi's two forms (one for 0
// and 1, other). The words for the suite's recurring terms are in
// GLOSSARY-hi.md beside this file, which a change of a word here follows.
// Drafted by machine and checked against the list by
// tests/catalogues.test.js; a native speaker's review is still to come.

