  'Accessibility: Investigate': 'पहुँच-योग्यता: जाँच करें',
  'Accessibility: Investigate — open the Accessibility pane': 'पहुँच-योग्यता: जाँच करें — पहुँच-योग्यता फलक खोलें',
  'Account': 'खाता',
  'Accounting': 'लेखांकन',
  'Accounts': 'खाते',
  'Accounts (JSON)': 'खाते (JSON)',
  'Accounts — a CalDAV or CardDAV server (iCloud, Fastmail, Nextcloud and the like) kept in step with this computer': 'खाते — कोई CalDAV या CardDAV सर्वर (iCloud, Fastmail, Nextcloud आदि) जो इस कंप्यूटर के साथ सिंक रहता है',
  'Across every account': 'सभी खातों में',
  'Action': 'क्रिया',
  'Action Settings': 'क्रिया सेटिंग्स',
  'Action — what a click on the selected shape does in the show: another slide, the end of the show, or a web address': 'क्रिया — शो में चयनित आकृति पर क्लिक करने से क्या होता है: कोई अन्य स्लाइड, शो का अंत, या कोई वेब पता',
  'Active sheet': 'सक्रिय शीट',
  'Activity': 'गतिविधि',
  'Actual Size': 'वास्तविक आकार',
  'Actual size': 'वास्तविक आकार',
  'Add': 'जोड़ें',
  'Add Animation': 'एनिमेशन जोड़ें',
  'Add Animation — another effect on the selected shape, after its others': 'एनिमेशन जोड़ें — चयनित आकृति पर उसके अन्य प्रभावों के बाद एक और प्रभाव',
  'Add Animation — select a shape first': 'एनिमेशन जोड़ें — पहले कोई आकृति चुनें',
  'Add Audio': 'ऑडियो जोड़ें',
