  'Effect Options — pick an effect with a direction (Fly In, Float In, Split, Wipe, Spin), or one on words of more than one paragraph': 'प्रभाव विकल्प — कोई दिशा वाला प्रभाव चुनें (फ़्लाई इन, फ़्लोट इन, स्प्लिट, वाइप, स्पिन), या एक से अधिक अनुच्छेदों वाले शब्दों पर लगा कोई प्रभाव',
