  'Effects reach shapes styled from the theme, as Excel\'s own shape styles are.': 'प्रभाव उन आकृतियों पर लागू होते हैं जिनकी शैली थीम से ली गई है, जैसे Excel की अपनी आकृति शैलियाँ।',
  'Effects — how shapes styled from the theme are filled, outlined and lifted; now {name}': 'प्रभाव — थीम से शैली लेने वाली आकृतियों का भरण, रूपरेखा और उभार कैसा हो; अभी {name}',
