  'Saved into this deck\'s theme: every slide that takes its colours from the theme follows, and Undo puts the old ones back.': 'इस प्रस्तुति की थीम में सहेजा गया: थीम से रंग लेने वाली हर स्लाइड इसका अनुसरण करती है, और “पूर्ववत करें” पुराने रंग वापस ले आता है।',
  'Saved into this workbook\'s theme: every cell, table, chart and shape that takes its colours from the theme follows, and Undo puts the old ones back.': 'इस कार्यपुस्तिका की थीम में सहेजा गया: थीम से रंग लेने वाले सभी कक्ष, तालिकाएँ, चार्ट और आकृतियाँ इसका अनुसरण करते हैं, और “पूर्ववत करें” पुराने रंग वापस ले आता है।',
