  'Select a cell in a list with a header row first — Subtotal groups the rows under it': 'पहले शीर्षलेख पंक्ति वाली किसी सूची में कोई कक्ष चुनें — “उप-योग” उसके नीचे की पंक्तियों को समूहित करता है',
  'Select a cell inside your data first — a filter needs a range.': 'पहले अपने डेटा के अंदर कोई कक्ष चुनें — फ़िल्टर के लिए एक श्रेणी चाहिए।',
  'Select a cell with a formula in it, then Evaluate Formula steps through it.': 'सूत्र वाला कोई कक्ष चुनें, फिर “सूत्र का मूल्यांकन करें” उसे चरण-दर-चरण दिखाता है।',
  'Select a drawing first — click it, or pick it in the Selection Pane.': 'पहले कोई आरेखण चुनें — उस पर क्लिक करें, या उसे चयन फलक में चुनें।',
  'Select a drawing to turn first.': 'घुमाने के लिए पहले कोई आरेखण चुनें।',
  'Select a group to ungroup': 'समूह हटाने के लिए कोई समूह चुनें',
  'Select a group to ungroup.': 'समूह हटाने के लिए कोई समूह चुनें।',
  'Select a picture, shape, chart or slicer first — click it on the sheet, or in the Selection Pane.': 'पहले कोई चित्र, आकृति, चार्ट या स्लाइसर चुनें — शीट पर या चयन फलक में उस पर क्लिक करें।',
  'Select a picture, shape, chart or slicer first.': 'पहले कोई चित्र, आकृति, चार्ट या स्लाइसर चुनें।',
  'Select a shape first.': 'पहले कोई आकृति चुनें।',
  'Select a text box first — click it once': 'पहले कोई टेक्स्ट बॉक्स चुनें — उस पर एक बार क्लिक करें',
  'Select a text box or a shape first.': 'पहले कोई टेक्स्ट बॉक्स या आकृति चुनें।',
  'Select a timeline and its values — dates in one column, numbers in the next — or put the cursor in them.': 'एक समयरेखा और उसके मान चुनें — एक स्तंभ में दिनांक, अगले में संख्याएँ — या कर्सर उनके भीतर रखें।',
  'Select a word in the document to put this one in its place.': 'इस शब्द को उसकी जगह रखने के लिए दस्तावेज़ में कोई शब्द चुनें।',
  'Select a word, or type one above.': 'कोई शब्द चुनें, या ऊपर कोई शब्द टाइप करें।',
