  'Show announcements from office.rutba.io — once a day at most. It sends the version and the operating system, and no identifier of any kind, so what is counted at the other end is "a copy opened somewhere", never you. It is also the only way we know the suite is being used at all.': 'office.rutba.io से घोषणाएँ दिखाएँ — दिन में अधिकतम एक बार। यह संस्करण और ऑपरेटिंग सिस्टम भेजता है, और किसी भी प्रकार का कोई पहचानकर्ता नहीं, इसलिए दूसरी ओर जो गिना जाता है वह “कहीं खोली गई एक प्रति” होती है, आप कभी नहीं। हमें यह पता चलने का भी यही एकमात्र तरीका है कि सुइट का उपयोग हो भी रहा है।',
