  'Show — the workbook as the picked view kept it': 'दिखाएँ — कार्यपुस्तिका वैसी, जैसी चुने गए दृश्य ने उसे सहेजा था',
  'Shown when the pointer rests on the cell. Optional.': 'पॉइंटर के कक्ष पर रुकने पर दिखाया जाता है। वैकल्पिक।',
  'Shown when the pointer rests on the cell; Excel shows it the same way.': 'पॉइंटर के कक्ष पर रुकने पर दिखाया जाता है; Excel भी इसे इसी तरह दिखाता है।',
  'Shows a list of ideas one under the other, each in a wide rounded box.': 'विचारों की सूची एक के नीचे एक दिखाता है, हर विचार एक चौड़े, गोल कोनों वाले बॉक्स में।',
  'Shows each top item over the items under it — a line to each. Tab a line in to put it under the one above.': 'हर शीर्ष आइटम को उसके नीचे वाले आइटमों के ऊपर दिखाता है — हर एक तक एक रेखा। किसी पंक्ति को ऊपर वाली पंक्ति के नीचे रखने के लिए उसे Tab से अंदर करें।',
  'Shows ideas that need not follow one another, each in a box of its own, the boxes in rows.': 'ऐसे विचार दिखाता है जिनका एक-दूसरे के क्रम में आना ज़रूरी नहीं, हर विचार अपने अलग बॉक्स में, और बॉक्स पंक्तियों में।',
  'Shows stages that come round again, in circles on a ring, clockwise from the top.': 'बार-बार लौटकर आने वाले चरण दिखाता है, एक घेरे पर बने वृत्तों में, ऊपर से दक्षिणावर्त।',
  'Shows the stages of a process moving forward, each a chevron pointing to the next.': 'आगे बढ़ती किसी प्रक्रिया के चरण दिखाता है, हर चरण एक शेवरॉन जो अगले की ओर इंगित करता है।',
  'Shows the steps of a process in order, left to right, an arrow from each to the next.': 'किसी प्रक्रिया के चरण क्रम से, बाएँ से दाएँ दिखाता है, हर चरण से अगले तक एक तीर।',
