  'This slide has no narration to play.': 'इस स्लाइड पर चलाने के लिए कोई वर्णन नहीं है।',
  'This slide is in no section.': 'यह स्लाइड किसी अनुभाग में नहीं है।',
  'This slide is in no section. Add Section starts one at it.': 'यह स्लाइड किसी अनुभाग में नहीं है। “अनुभाग जोड़ें” इसी स्लाइड से एक अनुभाग शुरू करता है।',
  'This slide is no longer in the deck': 'यह स्लाइड अब प्रस्तुति में नहीं है',
  'This slide\'s animations are laid out in a way this cannot rewrite; they are kept as they are.': 'इस स्लाइड के एनिमेशन इस तरह व्यवस्थित हैं कि यह उन्हें फिर से नहीं लिख सकता; उन्हें जैसे हैं वैसे ही रखा गया है।',
  'This slide\'s transition is now on every slide': 'इस स्लाइड का संक्रमण अब हर स्लाइड पर है',
  'This table has cells merged down a column — split them before sorting its rows.': 'इस तालिका में किसी स्तंभ में नीचे की ओर मर्ज किए गए कक्ष हैं — इसकी पंक्तियाँ सॉर्ट करने से पहले उन्हें विभाजित करें।',
  'This table has horizontally merged cells — its columns cannot be restructured yet.': 'इस तालिका में क्षैतिज रूप से मर्ज किए गए कक्ष हैं — इसके स्तंभों की संरचना अभी बदली नहीं जा सकती।',
  'This table has no column widths of its own to share out.': 'इस तालिका की अपनी कोई स्तंभ चौड़ाई नहीं है जिसे बाँटा जा सके।',
  'This table has no grid to split a cell in.': 'इस तालिका में कोई ग्रिड नहीं है जिसमें कक्ष विभाजित किया जा सके।',
  'This table has something between its rows that sorting would lose.': 'इस तालिका की पंक्तियों के बीच कुछ ऐसा है जो सॉर्ट करने पर खो जाएगा।',
  'This table has vertically merged cells — rows through a merge cannot be restructured yet.': 'इस तालिका में लंबवत रूप से मर्ज किए गए कक्ष हैं — किसी मर्ज से होकर जाने वाली पंक्तियों की संरचना अभी बदली नहीं जा सकती।',
  'This video plays in PowerPoint; this window cannot show its picture, so it stands as a plain poster.': 'यह वीडियो PowerPoint में चलता है; यह विंडो इसका चित्र नहीं दिखा सकती, इसलिए यह एक साधारण पोस्टर के रूप में दिखता है।',
  'This workbook has no comments.': 'इस कार्यपुस्तिका में कोई टिप्पणी नहीं है।',
  'This workbook in a second window': 'यह कार्यपुस्तिका दूसरी विंडो में',
  'This workbook is password-protected': 'यह कार्यपुस्तिका पासवर्ड से सुरक्षित है',
  'This workbook is too large for a script to read at once': 'यह कार्यपुस्तिका इतनी बड़ी है कि कोई स्क्रिप्ट इसे एक साथ नहीं पढ़ सकती',
  'This workbook: {name}': 'यह कार्यपुस्तिका: {name}',
  'This {noun} already needs a password to open. Type a new one to change it, or leave both boxes empty to remove it.': 'इस {noun} को खोलने के लिए पहले से ही पासवर्ड आवश्यक है। इसे बदलने के लिए नया पासवर्ड टाइप करें, या इसे हटाने के लिए दोनों बॉक्स खाली छोड़ दें।',
  'Those two requests, and the mail and calendar servers you set up yourself, are everything Rutba Office ever contacts. Your documents, your mail and what you do with them never leave this computer.': 'वे दो अनुरोध, और वे मेल और कैलेंडर सर्वर जिन्हें आपने स्वयं सेट किया है, बस यही सब हैं जिनसे Rutba Office कभी संपर्क करता है। आपके दस्तावेज़, आपकी मेल और आप उनके साथ जो करते हैं, वह सब कभी इस कंप्यूटर से बाहर नहीं जाता।',
  'Three': 'तीन',
  'Three Lines': 'तीन पंक्तियाँ',
  'Three columns': 'तीन स्तंभ',
  'Through': 'आर-पार',
